import os
from datetime import datetime, timedelta, timezone
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def query_metric_data(
    namespace: str,
    metric_name: str,
    resource_labels: Optional[Dict[str, str]] = None,
    dimensions: Optional[Dict[str, str]] = None,
    statistic: str = "Average",
    period: int = 300,
    start_time: Optional[datetime] = None,
    end_time: Optional[datetime] = None,
    region_name: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """
    Query Amazon CloudWatch metric data filtered by resource labels/dimensions.

    Args:
        namespace: CloudWatch metric namespace (e.g. "AWS/EC2").
        metric_name: Metric name to query (e.g. "CPUUtilization").
        resource_labels: Optional label map to translate into dimension filters.
        dimensions: Optional explicit CloudWatch dimensions map.
        statistic: CloudWatch statistic to return (e.g. "Average", "Sum").
        period: Granularity in seconds.
        start_time: Query start time; defaults to last 1 hour.
        end_time: Query end time; defaults to now.
        region_name: AWS region; defaults to AWS_REGION/AWS_DEFAULT_REGION.

    Returns:
        A list of datapoints sorted by timestamp ascending. Each datapoint is a dict
        containing Timestamp, Value, and optional Unit.
    """
    if start_time is None:
        end_time = end_time or datetime.now(timezone.utc)
        start_time = end_time - timedelta(hours=1)
    if end_time is None:
        end_time = datetime.now(timezone.utc)

    region_name = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    client = boto3.client("cloudwatch", region_name=region_name)

    dim_map: Dict[str, str] = {}
    if resource_labels:
        dim_map.update(resource_labels)
    if dimensions:
        dim_map.update(dimensions)

    metric_queries: List[Dict[str, Any]] = []

    if dim_map:
        metric_queries.append(
            {
                "Id": "m1",
                "MetricStat": {
                    "Metric": {
                        "Namespace": namespace,
                        "MetricName": metric_name,
                        "Dimensions": [{"Name": k, "Value": v} for k, v in dim_map.items()],
                    },
                    "Period": period,
                    "Stat": statistic,
                },
                "ReturnData": True,
            }
        )
    else:
        metric_queries.append(
            {
                "Id": "m1",
                "MetricStat": {
                    "Metric": {"Namespace": namespace, "MetricName": metric_name},
                    "Period": period,
                    "Stat": statistic,
                },
                "ReturnData": True,
            }
        )

    try:
        response = client.get_metric_data(
            MetricDataQueries=metric_queries,
            StartTime=start_time,
            EndTime=end_time,
            ScanBy="TimestampAscending",
        )
    except (ClientError, BotoCoreError) as exc:
        raise RuntimeError(f"CloudWatch metric query failed: {exc}") from exc

    results = []
    for result in response.get("MetricDataResults", []):
        timestamps = result.get("Timestamps", [])
        values = result.get("Values", [])
        unit = result.get("Label")
        for ts, value in zip(timestamps, values):
            item = {"Timestamp": ts, "Value": value}
            if unit:
                item["Unit"] = unit
            results.append(item)

    results.sort(key=lambda x: x["Timestamp"])
    return results


def list_metrics_with_filters(
    namespace: Optional[str] = None,
    metric_name: Optional[str] = None,
    dimensions: Optional[Dict[str, str]] = None,
    region_name: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """
    List CloudWatch metrics filtered by namespace, metric name, and dimensions.
    """
    region_name = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    client = boto3.client("cloudwatch", region_name=region_name)

    kwargs: Dict[str, Any] = {}
    if namespace:
        kwargs["Namespace"] = namespace
    if metric_name:
        kwargs["MetricName"] = metric_name
    if dimensions:
        kwargs["Dimensions"] = [{"Name": k, "Value": v} for k, v in dimensions.items()]

    metrics: List[Dict[str, Any]] = []
    paginator = client.get_paginator("list_metrics")

    try:
        for page in paginator.paginate(**kwargs):
            metrics.extend(page.get("Metrics", []))
    except (ClientError, BotoCoreError) as exc:
        raise RuntimeError(f"CloudWatch list_metrics failed: {exc}") from exc

    return metrics
